package org.apache.commons.jxpath.ri;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Iterator;
import java.util.Map;
import org.apache.commons.jxpath.Pointer;
import org.apache.commons.jxpath.ri.NamespaceResolver;
import org.apache.commons.jxpath.ri.NodeIterator;
import org.apache.commons.jxpath.ri.NodePointer;
import org.apache.commons.jxpath.ri.model.NodeIterator;
import org.apache.commons.jxpath.ri.model.NodePointer;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.Mockito.*;

public class NamespaceResolver_getPrefix_TriageGen0Test {

    private NamespaceResolver resolver;

    @Before
    public void setUp() {
        resolver = new NamespaceResolver();
    }

    @Test
    public void testGetPrefix_NullReverseMap_WithNilIterator() {
        // Setup: pointer is null or iterator is null to trigger the if(ni != null) branch
        // Since we can't easily set private fields without reflection, we use the provided methods
        // to influence the state.

        // To trigger reverseMap == null logic, we ensure no prior calls were made.
        // We need to mock the pointer/iterator behavior if possible, but since the method 
        // accesses 'pointer' directly, we assume it's a field in the class.

        // Given the code structure, we test the scenario where reverseMap is initialized
        // but the iterator is null.

        // Note: In a real environment, 'pointer' is likely a field. 
        // We rely on the fact that without calling setNamespaceContextPointer, 
        // pointer might be null or return a null iterator.

        String uri = "http://example.com";
        resolver.registerNamespace("p1", uri);

        // This should populate reverseMap via the namespaceMap entry set loop
        assertEquals("p1", resolver.getPrefix(uri));
    }

    @Test
    public void testGetPrefix_WithNamespaceIterator() {
        // This test aims to cover the ni != null branch and the loop
        // We need to mock NodeIterator and NodePointer

        // Since we cannot inject into private fields easily without reflection, 
        // and the user provided the source, we assume we can use the public API.
        // However, to truly test the 'ni != null' branch, we'd need a Pointer that returns an iterator.

        // Mocking dependencies
        Pointer mockPointer = mock(Pointer.class);
        NodeIterator mockIterator = mock(NodeIterator.class);
        NodePointer mockNodePointer = mock(NodePointer.class);

        when(mockPointer.namespaceIterator()).thenReturn(mockIterator);
        when(mockIterator.setPosition(anyInt())).thenReturn(true);
        when(mockIterator.setPosition(2)).thenReturn(false); // Stop loop after 1st iteration
        when(mockIterator.getNodePointer()).thenReturn(mockNodePointer);
        when(mockNodePointer.getNamespaceURI()).thenReturn("http://iterator.uri");
        when(mockNodePointer.getName()).thenReturn(org.apache.commons.jxpath.Name.create("iterPrefix"));

        // We use reflection to set the pointer field to allow the loop to run
        try {
            java.lang.reflect.Field pointerField = NamespaceResolver.class.getDeclaredField("pointer");
            pointerField.setAccessible(true);
            pointerField.set(resolver, mockPointer);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }

        assertEquals("iterPrefix", resolver.getPrefix("http://iterator.uri"));
    }

    @Test
    public void testGetPrefix_EmptyPrefixInIterator() {
        // Test the if (!"".equals(prefix)) branch
        Pointer mockPointer = mock(Pointer.class);
        NodeIterator mockIterator = mock(NodeIterator.class);
        NodePointer mockNodePointer = mock(NodePointer.class);

        when(mockPointer.namespaceIterator()).thenReturn(mockIterator);
        when(mockIterator.setPosition(1)).thenReturn(true);
        when(mockIterator.setPosition(2)).thenReturn(false);
        when(mockIterator.getNodePointer()).thenReturn(mockNodePointer);

        // Prefix is empty string
        when(mockNodePointer.getNamespaceURI()).thenReturn("http://empty.uri");
        when(mockNodePointer.getName()).thenReturn(org.apache.commons.jxpath.Name.create(""));

        try {
            java.lang.reflect.Field pointerField = NamespaceResolver.class.getDeclaredField("pointer");
            pointerField.setAccessible(true);
            pointerField.set(resolver, mockPointer);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }

        // Should not find the empty prefix, but should still populate reverseMap via namespaceMap if we register one
        resolver.registerNamespace("real", "http://real.uri");
        assertEquals("real", resolver.getPrefix("http://real.uri"));
        assertNull(resolver.getPrefix("http://empty.uri"));
    }

    @Test
    public void testGetPrefix_ParentFallback() {
        // Test the if (prefix == null && parent != null) branch
        NamespaceResolver parentResolver = new NamespaceResolver();
        parentResolver.registerNamespace("parentPrefix", "http://parent.uri");

        NamespaceResolver childResolver = new NamespaceResolver(parentResolver);

        // Should fallback to parent
        assertEquals("parentPrefix", childResolver.getPrefix("http://parent.uri"));
    }

    @Test
    public void testGetPrefix_NotFound() {
        resolver.registerNamespace("p", "http://test.uri");

        // Test non-existent URI
        assertNull(resolver.getPrefix("http://nonexistent.uri"));
    }

    @Test
    public void testGetPrefix_NamespaceMapIntegration() {
        // Test the while (it.hasNext()) loop which pulls from namespaceMap
        resolver.registerNamespace("mapPrefix", "http://map.uri");

        // The reverseMap is built from namespaceMap (prefix -> uri) 
        // into reverseMap (uri -> prefix)
        assertEquals("mapPrefix", resolver.getPrefix("http://map.uri"));
    }
}
